The update function:
JavaScript:
Game_BattlerBase.prototype.refresh = function() {
    this.stateResistSet().forEach(function(stateId) {
        this.eraseState(stateId);
    }, this);
    this._hp = this._hp.clamp(0, this.mhp);
    this._mp = this._mp.clamp(0, this.mmp);
    this._tp = this._tp.clamp(0, this.maxTp());
};
JavaScript:
let qTP_Team; // Should be init to 0 or leave it as You want
Game_BattlerBase.prototype.refresh = function() {
    this.stateResistSet().forEach(function(stateId) {
        this.eraseState(stateId);
    }, this);
    this._hp = this._hp.clamp(0, this.mhp);
    this._mp = this._mp.clamp(0, this.mmp);
    // this._tp = this._tp.clamp(0, this.maxTp());
    this._tp = 0; // Set all actors TP to 0 every "turn"
    // or
    this._tp = qTP_Team; // Set it to Team TP ( so all actors are showing same TP value )
};
You probably could detect damage as:
JavaScript:
Game_Battler.prototype.onDamage = function(value) {
    this.removeStatesByDamage();
    this.chargeTpByDamage(value / this.mhp);
    if( this.isEnemy() ){
        qTP_Team += 1; // Add 1 TP every time enemy is damaged
        if(qTP_Team > 3){ qTP_Team = 3; } // Check if TP is more than 3, if so, reduce to 3
    }
};
