        return this.friendsUnit()._tp >= this.skillTpCost(skill) && this._mp >= this.skillMpCost(skill);
    };

    Game_BattlerBase.prototype.paySkillCost = function(skill) {
        this._mp -= this.skillMpCost(skill);
        this.friendsUnit()._tp -= this.skillTpCost(skill);
    };

    Game_Battler.prototype.chargeTpByDamage = function(damageRate) {
    };

    Game_BattlerBase.prototype.setTp = function(tp) {
        this.friendsUnit()._tp = tp.clamp(0, this.maxTp());
    };

    var GU_Init = Game_Unit.prototype.initialize;
    Game_Unit.prototype.initialize = function() {
        GU_Init.call(this);
        this._tp = 0;
    };
